id'].' — '.$event['action'].' — '.$event['details'])?></p><?php endforeach;?></td></tr><?php endforeach;?></table></div>
<?php elseif($tab==='lots'): $rows=$db->query("SELECT l.*,a.reference,f.nom fournisseur,(SELECT COUNT(*) FROM stock_mouvements m WHERE m.lot_id=l.id AND m.type='reception') entrees FROM stock_lots l JOIN stock_articles a ON a.id=l.article_id LEFT JOIN stock_fournisseurs f ON f.id=l.fournisseur_id ORDER BY l.id DESC")->fetchAll();$rows=pfStockRows($rows);?>
