<div class="form-row"><label>Emplacement de réception<select class="form-control" name="emplacement_id" required><option value="">Choisir</option><?php so($empl,'chemin');?></select></label><label>Projet<select class="form-control" name="projet_id"><option value="">Sans projet</option><?php so($projets,'nom');?></select></label></div>
<label>Contrôle réception / notes<input class="form-control" name="notes" maxlength="10000"></label><button class="btn btn-primary btn-sm">Créer le lot</button></form></details><?php endif;?>
